/**
 * Save state: schema, migration, atomic persistence.
 *
 * Everything the game knows lives in one JSON document. That is a deliberate
 * choice with three consequences worth stating:
 *
 *   · A save is auditable. You can open it, read it, diff it, and decide the
 *     engine lied. That is the difference between a game you own and a service
 *     you rent.
 *   · The engine is the only writer. The model reads through `digest` and
 *     writes only through tool calls that the engine validates.
 *   · Writes are atomic (temp + rename). `node::Start` runs once per process on
 *     this platform, so a half-written save after a crash is not recoverable by
 *     restarting — it must never happen in the first place.
 *
 * Schema changes go through `migrate`, which is additive: an old save keeps
 * working and simply gains defaults. There is no "your save is incompatible"
 * path, because a personal game should survive its own updates.
 */

import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { seedFrom } from './rng.js'

export const SCHEMA = 1
export const SAVE_DIR = '.sanguo'
export const SAVE_FILE = 'save.json'
export const HISTORY_FILE = 'history.jsonl'

/** Attributes at birth. Four are mediocre. 魅 is not. */
export const BIRTH_ATTRS = { wu: 42, tong: 40, zhi: 48, zheng: 45, mei: 78 }

/** The three counters that compound. Everything else is flow. */
export const BIRTH_COUNTERS = { fame: 5, trust: 20, talent: 0 }

/** Material position at birth: a widow's son with a straw-sandal trade. */
export const BIRTH_RESOURCES = { gold: 3, grain: 1, troops: 0, hp: 100 }

/** The opening moment: 161 AD, 涿县, age 0 — but play starts at 184. */
export const BIRTH_CLOCK = { year: 161, month: 1, day: 1, turn: 0 }
export const PLAY_START_CLOCK = { year: 161, month: 1, day: 1, turn: 0 }
export const PLAY_START_AGE = 0

/** Clamp helper shared by every writer. */
function clamp(value, low, high) {
  const numeric = Number.isFinite(value) ? value : low
  return Math.min(high, Math.max(low, numeric))
}

/** A fresh save. `name` only affects the RNG seed, so a named run replays. */
export function createSave(name) {
  const seedName = typeof name === 'string' && name.length > 0 ? name : 'liubei'
  return {
    schema: SCHEMA,
    seed: seedFrom(seedName),
    rng: seedFrom(seedName),
    clock: { ...PLAY_START_CLOCK },
    age: PLAY_START_AGE,
    act: 'zhuojun',
    actName: '第一幕·涿郡',
    scene: 0,
    player: {
      name: '刘备',
      courtesy: '玄德',
      attrs: { ...BIRTH_ATTRS },
      counters: { ...BIRTH_COUNTERS },
      resources: { ...BIRTH_RESOURCES },
      tags: ['寒门', '织席贩履', '汉室宗亲（远支）'],
      titles: []
    },
    drift: 0,
    people: {},
    flags: {},
    counters: { turnsPlayed: 0, choicesMade: 0, deviations: 0 },
    log: []
  }
}

/**
 * Bring an older save up to the current schema.
 *
 * Additive only. A missing field gets its default; a present field is trusted
 * unless it is out of range (then it is clamped, never reset — losing a
 * player's progress to a range check would be worse than a slightly odd save).
 */
export function migrate(raw) {
  const save = raw && typeof raw === 'object' ? raw : {}
  const base = createSave('liubei')

  const merged = {
    ...base,
    ...save,
    schema: SCHEMA
  }

  merged.clock = { ...base.clock, ...(save.clock ?? {}) }
  merged.age = Number.isFinite(save.age) ? save.age : base.age
  merged.act = typeof save.act === 'string' && save.act.length > 0 ? save.act : base.act
  merged.actName = typeof save.actName === 'string' && save.actName.length > 0 ? save.actName : base.actName
  merged.scene = Number.isFinite(save.scene) ? save.scene : 0
  merged.seed = Number.isFinite(save.seed) ? save.seed >>> 0 : base.seed
  merged.rng = Number.isFinite(save.rng) ? save.rng >>> 0 : merged.seed
  merged.drift = clamp(Number(save.drift), 0, 100)

  const player = save.player ?? {}
  merged.player = {
    ...base.player,
    ...player,
    attrs: { ...base.player.attrs, ...(player.attrs ?? {}) },
    counters: { ...base.player.counters, ...(player.counters ?? {}) },
    resources: { ...base.player.resources, ...(player.resources ?? {}) },
    tags: Array.isArray(player.tags) ? player.tags : base.player.tags,
    titles: Array.isArray(player.titles) ? player.titles : base.player.titles
  }

  // Attributes are 0..100 by definition; a save outside that range came from a
  // hand edit or an old bug. Clamp rather than reject.
  for (const key of Object.keys(merged.player.attrs)) {
    merged.player.attrs[key] = clamp(merged.player.attrs[key], 0, 100)
  }
  for (const key of ['fame', 'trust', 'talent']) {
    merged.player.counters[key] = clamp(merged.player.counters[key], 0, 100)
  }
  for (const key of ['gold', 'grain', 'troops', 'hp']) {
    merged.player.resources[key] = Math.max(0, Math.trunc(merged.player.resources[key] ?? 0))
  }

  merged.people = save.people && typeof save.people === 'object' ? save.people : {}
  merged.flags = save.flags && typeof save.flags === 'object' ? save.flags : {}
  merged.counters = { ...base.counters, ...(save.counters ?? {}) }
  merged.log = Array.isArray(save.log) ? save.log : []

  return merged
}

/** Directory that holds the save for one workspace. */
export function saveDir(workdir) {
  return join(workdir, SAVE_DIR)
}

export function savePath(workdir) {
  return join(saveDir(workdir), SAVE_FILE)
}

export function historyPath(workdir) {
  return join(saveDir(workdir), HISTORY_FILE)
}

/** True when a save exists. Used to decide between "continue" and "new game". */
export async function exists(workdir) {
  try {
    await readFile(savePath(workdir), 'utf8')
    return true
  } catch (error) {
    return false
  }
}

/**
 * Load a save, or null when there is none.
 *
 * A corrupt save is surfaced as an error rather than silently replaced: losing
 * a run to a parse failure without saying so is the worst possible outcome.
 */
export async function load(workdir) {
  let text
  try {
    text = await readFile(savePath(workdir), 'utf8')
  } catch (error) {
    if (error?.code === 'ENOENT') {
      return null
    }
    throw error
  }
  let parsed
  try {
    parsed = JSON.parse(text)
  } catch (error) {
    throw new Error(`存档已损坏，无法解析：${error.message}（文件：${savePath(workdir)}）`)
  }
  return migrate(parsed)
}

/**
 * Persist atomically: write a sibling temp file, then rename over the target.
 *
 * The temp name carries the pid so two concurrent writers cannot clobber each
 * other's staging file. Rename is atomic on the same filesystem, which is the
 * only guarantee we need.
 */
export async function save(workdir, state) {
  const dir = saveDir(workdir)
  await mkdir(dir, { recursive: true })
  const target = savePath(workdir)
  const staging = `${target}.${process.pid}.tmp`
  const body = JSON.stringify(state, null, 2)
  await writeFile(staging, body, 'utf8')
  await rename(staging, target)
  return target
}

/** Append one history record. History is append-only; the save is the snapshot. */
export async function appendHistory(workdir, record) {
  const dir = saveDir(workdir)
  await mkdir(dir, { recursive: true })
  const line = `${JSON.stringify(record)}\n`
  // `appendFile` is not used because we want an explicit flag set on the first
  // write of a run, and because a torn line would break replay.
  const target = historyPath(workdir)
  const existing = await readFile(target, 'utf8').catch(() => '')
  const next = existing.endsWith('\n') || existing.length === 0 ? existing + line : `${existing}\n${line}`
  const staging = `${target}.${process.pid}.tmp`
  await writeFile(staging, next, 'utf8')
  await rename(staging, target)
  return target
}

/** Read the append-only history as records. Tolerates a torn final line. */
export async function readHistory(workdir) {
  const text = await readFile(historyPath(workdir), 'utf8').catch(() => '')
  const out = []
  for (const line of text.split('\n')) {
    const trimmed = line.trim()
    if (trimmed.length === 0) continue
    try {
      out.push(JSON.parse(trimmed))
    } catch (error) {
      // A torn final line is expected if the process died mid-write; skipping
      // it is correct because the save snapshot is authoritative anyway.
    }
  }
  return out
}

/** Directory that holds the data files (acts.json, people.json). */
export function dataDir(packageRoot) {
  return join(packageRoot, 'data')
}

export { clamp }
